#!/usr/bin/env bash
# Builds dist/cloud-setup.sh: a setup script for a Claude Code cloud
# environment that installs the four skills into ~/.claude/skills on the VM.
#
# Cloud sessions don't read ~/.claude/skills from your machine. Add the
# generated file as the setup script of your own environment at claude.ai/code.
# Rebuild and re-add it after changing anything in skills/ or lib/.
set -euo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
out="$here/dist/cloud-setup.sh"
eof='__TASK_PIPELINE_EOF__'

if grep -rqF "$eof" "$here/skills" "$here/lib"; then
  echo "error: a source file contains the heredoc delimiter $eof" >&2
  exit 1
fi

# Prints a quoted heredoc that recreates file $2 at path $1 on the VM.
emit() {
  printf "cat >\"%s\" <<'%s'\n" "$1" "$eof"
  cat "$2"
  [ -z "$(tail -c 1 "$2")" ] || echo
  echo "$eof"
}

mkdir -p "$here/dist"
{
  echo '#!/bin/bash'
  echo '# Generated by build-cloud-setup.sh. Installs the /rewrite, /prepare,'
  echo '# /instruct and /start skills for Claude Code cloud sessions.'
  echo 'dest="$HOME/.claude/skills"'
  echo 'tmp="$(mktemp)"'
  emit '$tmp' "$here/lib/task.sh"
  for dir in "$here"/skills/*/; do
    name="$(basename "$dir")"
    echo
    echo "mkdir -p \"\$dest/$name/scripts\""
    emit "\$dest/$name/SKILL.md" "$dir/SKILL.md"
    echo "cp \"\$tmp\" \"\$dest/$name/scripts/task.sh\""
    echo "chmod +x \"\$dest/$name/scripts/task.sh\""
  done
  echo
  echo 'rm -f "$tmp"'
  echo 'exit 0'
} >"$out"
chmod +x "$out"

size="$(wc -c <"$out" | tr -d ' ')"
echo "Wrote $out ($size bytes; a setup script can be up to 64 KB)"
